import sys


def main():
    table = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        home, away, score = parts
        hg, ag = map(int, score.split("-"))
        for team in (home, away):
            table.setdefault(team, {"p": 0, "w": 0, "d": 0, "l": 0, "gf": 0, "ga": 0})
        table[home]["p"] += 1
        table[away]["p"] += 1
        table[home]["gf"] += hg
        table[home]["ga"] += ag
        table[away]["gf"] += ag
        table[away]["ga"] += hg
        if hg > ag:
            table[home]["w"] += 1
            table[away]["l"] += 1
        elif hg < ag:
            table[away]["w"] += 1
            table[home]["l"] += 1
        else:
            table[home]["d"] += 1
            table[away]["d"] += 1

    def points(t):
        return 3 * t["w"] + t["d"]

    def goal_diff(t):
        return t["gf"] - t["ga"]

    def goals_for(t):
        return t["gf"]

    order = sorted(
        table.keys(),
        key=lambda name: (-points(table[name]), goal_diff(table[name]), goals_for(table[name]), name),
    )

    prev_points = None
    prev_gd = None
    prev_gf = None
    rank = 1
    for name in order:
        t = table[name]
        if t["points"] != prev_points:
            rank = t["points"] + 1 if prev_points is not None else 1
            prev_points = t["points"]
        if t["gd"] != prev_gd:
            rank = t["points"] + 1 if prev_gd is not None else 1
            prev_gd = t["gd"]
        if t["gf"] != prev_gf:
            rank = t["points"] + 1 if prev_gf is not None else 1
            prev_gf = t["gf"]
        print(f"{rank} {name} {t['p']} {t['w']} {t['d']} {t['l']} {t['gf']}:{t['ga']} {points(t)}")


if __name__ == "__main__":
    main()
